const input = $input.first().json;
if (!input.verifiedFacts || typeof input.verifiedFacts !== 'object') throw new Error('verifiedFacts is required');
if (!input.deterministic?.tables || !input.deterministic?.skeleton) throw new Error('deterministic tables and skeleton are required');
const allowed = ['identity','inner-world','integration','dynamics'];
const packs = input.narrativeFactPacks;
if (!Array.isArray(packs) || packs.length !== 4 || new Set(packs.map(p => p.sectionId)).size !== 4 || packs.some(p => !allowed.includes(p.sectionId))) throw new Error('narrativeFactPacks must contain exactly the four compiler slots');
for (const pack of packs) { if (!pack.wordLimit || pack.wordLimit.max < 1 || pack.wordLimit.max > 700 || !Array.isArray(pack.facts)) throw new Error(`invalid fact pack ${pack.sectionId}`); }
return allowed.map(sectionId => ({ json: { ...input, narrativeFactPack: packs.find(p => p.sectionId === sectionId), sectionId, _deterministicSnapshot: JSON.parse(JSON.stringify(input.deterministic)) } }));

const item = $input.first().json;
const original = $('Loop Over Four Compiler Slots').item.json;
let response;
try {
  const raw = item.text ?? item.output ?? item.content ?? item;
  response = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) { response = null; }
let valid = !!response && response.sectionId === original.sectionId && Array.isArray(response.blocks) && response.blocks.length > 0;
const allowed = new Set((original.narrativeFactPack.facts || []).map(f => f.id));
if (valid) for (const block of response.blocks) if (!['narrative','reflection','practical'].includes(block.role) || typeof block.prose !== 'string' || !block.prose.trim() || !Array.isArray(block.factIds) || block.factIds.some(id => !allowed.has(id))) valid = false;
return [{ json: { ...original, narrativeBlock: valid ? { sectionId: original.sectionId, blocks: response.blocks } : null, _primaryValid: valid, _validationError: valid ? null : `strict narrative validation failed for ${original.sectionId}` } }];

const item = $input.first().json;
const original = $('Loop Over Four Compiler Slots').item.json;
let response;
try {
  const raw = item.text ?? item.output ?? item.content ?? item;
  response = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) { response = null; }
if (!response || response.sectionId !== original.sectionId || !Array.isArray(response.blocks) || response.blocks.length < 1) throw new Error(`repair rejected for ${original.sectionId}`);
const allowed = new Set((original.narrativeFactPack.facts || []).map(f => f.id));
for (const block of response.blocks) { if (!['narrative','reflection','practical'].includes(block.role) || typeof block.prose !== 'string' || !block.prose.trim() || !Array.isArray(block.factIds) || block.factIds.some(id => !allowed.has(id))) throw new Error(`repair strict validation failed for ${original.sectionId}`); }
return [{ json: { ...original, narrativeBlock: { sectionId: original.sectionId, blocks: response.blocks }, _repairAttempt: 1 } }];
